#!/usr/bin/env python3
"""Run-specific E1 gateway dossier, generated by CI, never an independent report.

Exercises the published CLI in a subprocess; rejects mismatched and false-success
results. Output belongs to validation/ and is uploaded with existing CI evidence.
"""
import copy
import hashlib
import importlib.metadata
import json
import platform
import subprocess
import sys
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
CASE = ROOT / "examples/delegated-agent-purchase/adopter-gateway-case.json"
CLI = "examples/delegated-agent-purchase/adopter_gateway.py"
OUTPUT = ROOT / "validation/adopter-gateway-evaluation.json"


def utc():
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def cases():
    return (
        ("valid-local", {}, "permit", "SCENARIO_LOCAL_CHECKS_SATISFIED", 0),
        ("other-agent", {"request.agent": "other-agent"}, "deny", "DELEGATION_BINDING_MISMATCH", 0),
        ("invalid-parent", {"delegation.parentAuthority": "another-mandate"}, "deny", "DELEGATION_BINDING_MISMATCH", 0),
        ("amplified-resource", {"delegation.delegatedScope.resources": ["other-merchant"]}, "deny", "DELEGATION_AMPLIFICATION", 0),
        ("out-of-scope-effect", {"request.effect": "refund"}, "deny", "REQUEST_OUT_OF_SCOPE", 0),
        ("revoked-authority", {"authority.status": "revoked"}, "deny", "INACTIVE_AUTHORITY_OR_DELEGATION", 0),
        ("revoked-delegation", {"delegation.status": "revoked"}, "deny", "INACTIVE_AUTHORITY_OR_DELEGATION", 0),
        ("expired", {"authority.effectiveUntil": "2026-10-01T00:00:00Z"}, "deny", "OUTSIDE_EFFECTIVE_PERIOD", 0),
        ("not-yet-effective", {"delegation.effectiveFrom": "2026-12-01T00:00:00Z"}, "deny", "OUTSIDE_EFFECTIVE_PERIOD", 0),
        ("missing-observation", {"observations.authorityStatus": None}, "indeterminate", "MISSING_OBSERVATION", 0),
        ("unknown-observation", {"observations.authorityStatus.value": "unknown"}, "indeterminate", "UNRESOLVED_OBSERVATION", 0),
        ("stale-observation", {"observations.authorityStatus.observedAt": "2026-01-01T00:00:00Z"}, "indeterminate", "STALE_OR_FUTURE_OBSERVATION", 0),
        ("unsupported-scope", {"authority.scope": {"opaquePurpose": "purchase"}}, "indeterminate", "UNSUPPORTED_SCOPE", 0),
        ("conflicting-observation", {"observations.authorityStatus.conflictingObservation": {"value": "revoked", "source": "another-provider"}}, "indeterminate", "INSUFFICIENT_OBSERVATION", 0),
        ("untrusted-source-label", {"observations.authorityStatus.source": "untrusted-claimant"}, "permit", "SCENARIO_LOCAL_CHECKS_SATISFIED", 0),
        ("invalid-json", None, "indeterminate", "INVALID_JSON", 2),
    )


def mutate(base, alterations):
    value = copy.deepcopy(base)
    for dotted, replacement in alterations.items():
        parts = dotted.split(".")
        target = value
        for part in parts[:-1]:
            target = target[part]
        target[parts[-1]] = replacement
    return value


def execute(command, input_text, timeout=15):
    return subprocess.run(command, cwd=ROOT, input=input_text, capture_output=True,
                          text=True, timeout=timeout, check=False)


def evaluate_all():
    baseline = json.loads(CASE.read_text(encoding="utf-8"))
    sha = subprocess.run(["git", "rev-parse", "HEAD"], cwd=ROOT, capture_output=True,
                         text=True, check=True).stdout.strip()
    command = [sys.executable, CLI]
    results = []
    for identifier, changes, status, reason, returncode in cases():
        bundle = mutate(baseline, changes) if changes is not None else None
        encoded = json.dumps(bundle, sort_keys=True) if bundle is not None else "invalid json"
        started = utc()
        process = execute(command, encoded)
        finished = utc()
        try:
            outcome = json.loads(process.stdout)
        except json.JSONDecodeError:
            outcome = {"status": "runner-failure", "reason": "NON_JSON_RESPONSE", "effectExecuted": None}
        expected = {"status": status, "reason": reason, "returncode": returncode,
                    "effectExecuted": False}
        actual = {"status": outcome.get("status"), "reason": outcome.get("reason"),
                  "returncode": process.returncode, "effectExecuted": outcome.get("effectExecuted")}
        accepted = (actual == expected and outcome.get("independentAssurance") is not True
                    and outcome.get("composedConformance") is not True)
        results.append({
            "id": identifier,
            "command": "python " + CLI + " <stdin>",
            "input": bundle if bundle is not None else "invalid json",
            "inputSha256": hashlib.sha256(encoded.encode("utf-8")).hexdigest(),
            "expected": expected, "observed": actual, "pass": accepted,
            "startedAt": started, "completedAt": finished,
            "stderr": process.stderr[:300],
            "limitations": (["WARNING: local permit persists despite unverified source label; NOT operational authorization"]
                            if identifier == "untrusted-source-label" else []),
        })
    return {
        "kind": "GAAM-repository-controlled-gateway-exercise",
        "synthetic": True, "evidenceClass": "E1-self-assessed",
        "independentImplementation": False, "independentAssurance": False,
        "sourceCommit": sha,
        "publishedReleaseReference": "v" + (ROOT / "VERSION").read_text().strip(),
        "normativeSemanticBaseline": "0.9.0",
        "profileScope": "bounded illustrative Foundation/Delegated Authority subset; no profile conformance",
        "implementation": {"name": "GAAM repository-authored gateway example", "source": CLI},
        "environment": {"python": platform.python_version(), "jsonschema": importlib.metadata.version("jsonschema"),
                        "platform": platform.platform(), "runner": "GitHub Actions or local checkout"},
        "evaluationClock": baseline["evaluationTime"],
        "policyContext": baseline["policy"],
        "unverified": ["identity and issuer authenticity", "source acceptance and current status provenance",
                       "portable scope and policy semantics", "multi-source conflict adjudication",
                       "decision receipt authenticity/retention/replay", "effect execution/remedy",
                       "independent implementer and E2/E3 evidence"],
        "cases": results,
        "summary": {"total": len(results), "passed": sum(x["pass"] for x in results),
                    "failed": sum(not x["pass"] for x in results)},
    }


def main():
    result = evaluate_all()
    OUTPUT.parent.mkdir(exist_ok=True)
    OUTPUT.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    print(f"Gateway E1 dossier: {result['summary']['passed']}/{result['summary']['total']} matched; {OUTPUT.relative_to(ROOT)}")
    return 0 if result["summary"]["failed"] == 0 else 1


if __name__ == "__main__":
    raise SystemExit(main())
